public void tick() {
        super.tick();

        if (this.level().isClientSide) {
            if (this.clientSideAttackStarted) {
                ++this.lifeTicks;
                if (this.lifeTicks == 55) {

                    double d0 = (2.0F * random.nextFloat() - 1.0F) * 0.4D;
                    double d1 = (2.0F * random.nextFloat() - 1.0F) * 0.4D ;
                    double d2 = this.getX() + d0;
                    double d3 = this.getY() + (double)random.nextFloat() * 2;
                    double d4 = this.getZ() + d1;
                    this.level().addParticle(ModParticle.PHANTOM_EMITTER.get(), d2, d3, d4, 0.0, 0.25D * random.nextDouble(), 0.0);

                }
                if (this.lifeTicks == 4) {

                    double d0 = this.getX();
                    double d1 = this.getY() + 0.1;
                    double d2 = this.getZ();

                    this.level().addParticle(new Cursed_MarkParticleOption(0.7F + this.random.nextFloat() * 0.3F), d0, d1, d2, 0, 0, 0);

                }
            }
        } else if (--this.warmupDelayTicks < 0) {
            if (this.warmupDelayTicks == -10) {
                if(getState() == 0) {
                    this.setState(1 + random.nextInt(4));
                }
            }
            if (this.warmupDelayTicks < -12 && this.warmupDelayTicks > -34) {
                for(LivingEntity livingentity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox())) {
                    this.damage(livingentity);
                }
            }


            if (!this.sentSpikeEvent) {
                this.level().broadcastEntityEvent(this, (byte)4);
                this.sentSpikeEvent = true;
            }

            if (++this.lifeTicks > 70) {
                this.discard();
            }
        }

    }

protected void damage(LivingEntity Hitentity) {
        LivingEntity livingentity = this.getCaster();
        if (Hitentity.isAlive() && !Hitentity.isInvulnerable() && Hitentity != livingentity) {
            if (this.tickCount % 5 == 0) {
                if (livingentity == null) {
                    Hitentity.hurt(this.damageSources().magic(), getDamage());
                } else {
                    if (!livingentity.isAlliedTo(Hitentity) && !Hitentity.isAlliedTo(livingentity)) {
                        Hitentity.hurt(CMDamageTypes.causeMaledictioMagicaeDamage(this, livingentity), getDamage());
                    }
                }
            }
        }
    }

